@startuml

class WebPortal {
  +versionNumber : string
  +url : string
}

class Building {
  +id : string
  +name : string
  +address : string
  +yearOfConstruction : int
}

class Entry {
  +name : string
  +public : boolean
}

class Image {
  +fileName : string
}

class User {
  +userName : string
  +emailAddress : string
  +password : string
}

class Administrator {
  +idCardNumber : string
}

class Comment {
}

enum EnergyClass {
  A
  B
  C
  D
}

WebPortal "1" -- "*" Building
Building "1" -- "1" EnergyClass
Building "1" *-- "*" Entry
Building "1" *-- "*" Image
Building "1" -- "0..1" Image : profile photo
User "1" -- "*" Building : owner
User "1" -- "*" Comment : writes
Building "1" -- "*" Comment : has
WebPortal "1" -- "*" User : hosts

Administrator extends User

@enduml

